WITH `t0` AS (SELECT `tenantId`, `entityId`, `category`, `state`, `part_specifications`, `matched_part_ids`, `countOfParts`, `updatedAt`, `partId` FROM `entity_ots_component` ARRAY JOIN `matched_part_ids` AS `partId` WHERE `tenantId` = {p0:String}) SELECT `t0`.`tenantId`, `t0`.`entityId`, `t0`.`category`, `t0`.`state`, `t0`.`part_specifications`, `t0`.`matched_part_ids`, `t0`.`countOfParts`, `t0`.`updatedAt`, `t0`.`partId` FROM `t0`
